INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21YBGXL', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A delivery service charges a flat fee of $\\$11$ per trip plus $\\$2$ per mile driven. The company reimburses drivers for trips costing more than $\\$37$. For how many miles, $m$, does the driver receive reimbursement?', NULL, $lyceon_json$[{"key":"A","text":"$m > 13$"},{"key":"B","text":"$m > 24$"},{"key":"C","text":"$m \\geq 13$"},{"key":"D","text":"$m > 18.5$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost of a trip is $2m + 11$. The driver is reimbursed when this cost is more than $\\$37$: $2m + 11 > 37$. Subtracting $11$ from both sides gives $2m > 26$, so $m > 13$. The distractor $m > 24$ comes from computing $37 - 11 = 26$ but then adding $26$ to $11$ instead of dividing, or otherwise mishandling the algebra to arrive at $24$. The distractor $m \\geq 13$ uses a non-strict inequality; the problem states "more than $\\$37$," which requires strict inequality (cost must exceed $\\$37$, not merely equal it). The distractor $m > 18.5$ comes from dividing $37$ by $2$ without first subtracting the flat fee.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22EHRDW', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line passes through the points $(4, 1)$ and $(10, 19)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-11', ARRAY['-11'], E'The slope is $\\frac{19 - 1}{10 - 4} = \\frac{18}{6} = 3$. Using point-slope form with $(4, 1)$: $y - 1 = 3(x - 4)$, so $y = 3x - 12 + 1 = 3x - 11$. The $y$-intercept is $-11$. A common error is computing the slope as $\\frac{10 - 4}{19 - 1} = \\frac{1}{3}$, which inverts rise and run. Another error is substituting incorrectly to get $b = -13$ by adding instead of subtracting.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22UJB96', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A chemical solution requires mixing $7$ milliliters of reagent A for every $3$ milliliters of reagent B. If a lab technician uses $21$ milliliters of reagent A, how many milliliters of reagent B are needed?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$9$"},{"key":"C","text":"$14$"},{"key":"D","text":"$49$"}]$lyceon_json$::jsonb, 'B', NULL, E'The ratio of reagent A to reagent B is $7:3$. Since $21 \\div 7 = 3$, the scale factor is $3$. Multiplying $3 \\times 3 = 9$ milliliters of reagent B are needed. The distractor $6$ results from doubling the $3$ in the ratio instead of applying the scale factor. The distractor $14$ comes from multiplying $7 \\times 2$ as if the ratio were $1:2$. The distractor $49$ results from multiplying $7 \\times 7$, confusing the components of the ratio.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM236HK1T', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'grid_in', E'A researcher collects data and determines that the line of best fit is $y = -3.5x + 89$. According to this model, for what value of $x$ does $y = 19$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '20', ARRAY['20'], E'Setting $y = 19$: $19 = -3.5x + 89$. Subtracting $89$ from both sides: $-70 = -3.5x$. Dividing both sides by $-3.5$: $x = 20$. A common error is mishandling the negative signs to get $x = -20$, or dividing $89$ by $3.5$ directly without subtracting $19$ first, which gives approximately $25.4$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23B0A99', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'A circle has center $(2, -7)$ and passes through the point $(11, 5)$. A chord of this circle has its midpoint at $(14, -1)$. What is the length of this chord?', NULL, $lyceon_json$[{"key":"A","text":"$6\\sqrt{21}$"},{"key":"B","text":"$6\\sqrt{5}$"},{"key":"C","text":"$3\\sqrt{5}$"},{"key":"D","text":"$15$"}]$lyceon_json$::jsonb, 'B', NULL, E'First find the radius. The distance from center $(2, -7)$ to the point $(11, 5)$ is $r = \\sqrt{(11-2)^2 + (5+7)^2} = \\sqrt{81 + 144} = \\sqrt{225} = 15$. Next, find the distance from the center to the midpoint of the chord: $d = \\sqrt{(14-2)^2 + (-1+7)^2} = \\sqrt{144 + 36} = \\sqrt{180}$. By the perpendicular-from-center-to-chord theorem, half the chord length is $\\sqrt{r^2 - d^2} = \\sqrt{225 - 180} = \\sqrt{45} = 3\\sqrt{5}$. The full chord length is $2 \\times 3\\sqrt{5} = 6\\sqrt{5}$. The value $6\\sqrt{21}$ results from using only the $y$-component of the distance to the midpoint: $d^2 = 36$, giving $\\sqrt{225 - 36} = \\sqrt{189} = 3\\sqrt{21}$ and chord $= 6\\sqrt{21}$. The value $3\\sqrt{5}$ is half the chord length, from forgetting to double. The value $15$ confuses the radius itself with the chord length.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24QY7SC', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A cylinder has a radius of $7$ cm and a height of $18$ cm. A cone has the same radius and the same height as the cylinder. What is the volume of the space inside the cylinder but outside the cone, in cubic centimeters? (Give your answer as a numerical coefficient of $\\pi$; for example, if the volume is $50\\pi$, enter $50$.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '588', ARRAY['588'], E'The volume of the cylinder is $\\pi r^2 h = \\pi(7)^2(18) = 882\\pi$. The volume of the cone is $\\frac{1}{3}\\pi r^2 h = \\frac{1}{3}(882\\pi) = 294\\pi$. The space inside the cylinder but outside the cone has volume $882\\pi - 294\\pi = 588\\pi$. The numerical coefficient is $588$. A common error is using $\\frac{1}{2}$ instead of $\\frac{1}{3}$ for the cone volume factor, giving $441\\pi$ for the cone and $441\\pi$ for the remaining space. Another error is computing $7^2 = 49$ but then multiplying $49 \\times 18$ incorrectly as $862$ instead of $882$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26U5EA4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of 600 households in a county and finds that 37% use solar panels. The margin of error is 3.8 percentage points at a 95% confidence level. There are 14,200 households in the county. Based on the survey, which of the following is a plausible estimate of the total number of households in the county that use solar panels?', NULL, $lyceon_json$[{"key":"A","text":"4,714"},{"key":"B","text":"6,106"},{"key":"C","text":"222"},{"key":"D","text":"2,840"}]$lyceon_json$::jsonb, 'A', NULL, E'The confidence interval for the proportion is 37% ± 3.8%, which is 33.2% to 40.8%. The plausible range for the total number of households is 0.332 × 14,200 = 4,714 to 0.408 × 14,200 = 5,794. The value 4,714 falls at the lower end of this interval. The distractor 6,106 exceeds the upper bound of the interval (5,794) and results from an arithmetic error such as using 43% instead of 40.8%. The distractor 222 applies 37% to the sample size (0.37 × 600 = 222) rather than the total county population, an equation setup error. The distractor 2,840 results from using 20% of the county households, reflecting partial reasoning that does not correctly use the survey proportion.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28MD24F', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $13$ units. What is the area of the circle, in square units?', NULL, $lyceon_json$[{"key":"A","text":"$26\\pi$"},{"key":"B","text":"$169\\pi$"},{"key":"C","text":"$169$"},{"key":"D","text":"$13\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a circle is $A = \\pi r^2 = \\pi(13)^2 = 169\\pi$. The value $26\\pi$ results from using the circumference formula $2\\pi r = 2\\pi(13) = 26\\pi$ instead of the area formula. The value $169$ correctly squares the radius but omits the factor of $\\pi$. The value $13\\pi$ uses $\\pi r$ rather than $\\pi r^2$, failing to square the radius.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28N679E', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one leg has length $20$ and the hypotenuse has length $101$. What is the length of the other leg?', NULL, $lyceon_json$[{"key":"A","text":"$81$"},{"key":"B","text":"$99$"},{"key":"C","text":"$\\sqrt{10601}$"},{"key":"D","text":"$91$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the Pythagorean theorem, $a^2 + 20^2 = 101^2$, so $a^2 = 10201 - 400 = 9801$. Since $\\sqrt{9801} = 99$, the other leg is $99$. The value $81$ comes from subtracting the lengths directly: $101 - 20 = 81$, which is not how the Pythagorean theorem works. The value $\\sqrt{10601}$ results from adding instead of subtracting: $101^2 + 20^2 = 10201 + 400 = 10601$. The value $91$ comes from an arithmetic error computing $10201 - 400 = 8281$ and then $\\sqrt{8281} = 91$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM298QC42', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What are the solutions to $x^2 - 5x - 36 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = -9$ and $x = 4$"},{"key":"B","text":"$x = 9$ and $x = -4$"},{"key":"C","text":"$x = 6$ and $x = -6$"},{"key":"D","text":"$x = 12$ and $x = -3$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factor $x^2 - 5x - 36$: find two numbers that multiply to $-36$ and add to $-5$. Those numbers are $-9$ and $4$, giving $(x - 9)(x + 4) = 0$, so $x = 9$ or $x = -4$. The distractor $x = -9$ and $x = 4$ reverses the signs. The distractor $x = 6$ and $x = -6$ incorrectly treats the equation as a difference of squares. The distractor $x = 12$ and $x = -3$ uses factors of $-36$ that sum to $9$ rather than $-5$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29CKGP4', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In a right triangle, one of the acute angles measures $\\theta$. If $\\sin(\\theta) = \\frac{11}{61}$, what is the value of $\\cos(\\theta)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '60/61', ARRAY['60/61', '0.983', '.983', '0.984', '.984'], E'In a right triangle, $\\sin(\\theta) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{11}{61}$. The adjacent side can be found using the Pythagorean theorem: $\\text{adjacent} = \\sqrt{61^2 - 11^2} = \\sqrt{3721 - 121} = \\sqrt{3600} = 60$. Therefore $\\cos(\\theta) = \\frac{60}{61}$. A common error is computing $\\cos(\\theta) = 1 - \\sin(\\theta) = 1 - \\frac{11}{61} = \\frac{50}{61}$, confusing the identity $\\sin^2(\\theta) + \\cos^2(\\theta) = 1$ with a linear relationship. Another error is subtracting the values directly: $61 - 11 = 50$, giving $\\frac{50}{61}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29EYYSY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A factory uses two machines. Machine P processes $14$ units per hour and Machine Q processes $7$ units per hour. Machine P runs for $9$ hours and Machine Q runs for $t$ hours. If the ratio of units processed by Machine P to units processed by Machine Q must equal $\\frac{3}{2}$, what is the value of $t$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$9$"},{"key":"C","text":"$12$"},{"key":"D","text":"$18$"}]$lyceon_json$::jsonb, 'C', NULL, E'Machine P processes $14 \\times 9 = 126$ units. Machine Q processes $7t$ units. The required ratio is $\\frac{126}{7t} = \\frac{3}{2}$. Cross-multiplying: $126 \\times 2 = 3 \\times 7t$, giving $252 = 21t$, so $t = 12$. The distractor $6$ comes from using only the rate ratio $\\frac{14}{7} = 2$ and setting $\\frac{9}{t} = \\frac{3}{2}$ without accounting for the different rates, yielding $t = 6$. The distractor $9$ results from assuming Machine Q must run the same number of hours as Machine P. The distractor $18$ comes from computing $\\frac{126}{7} = 18$, which would be the hours needed for Machine Q to match Machine P''s total output rather than achieving the $3:2$ ratio.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A91W1U', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A store marks up the wholesale cost of an item by $40\\%$ to set the retail price, then offers a seasonal discount of $15\\%$ off the retail price. If the wholesale cost of the item is $\\$70$, what is the final sale price after the discount?', NULL, $lyceon_json$[{"key":"A","text":"$\\$83.30$"},{"key":"B","text":"$\\$84.00$"},{"key":"C","text":"$\\$87.50$"},{"key":"D","text":"$\\$98.00$"}]$lyceon_json$::jsonb, 'A', NULL, E'The retail price is $70 \\times 1.40 = \\$98$. The seasonal discount is $98 \\times 0.15 = \\$14.70$, so the final price is $98 - 14.70 = \\$83.30$. The distractor $\\$84.00$ comes from applying a net $20\\%$ increase to $\\$70$ ($70 \\times 1.20 = 84$), incorrectly subtracting $15\\%$ from $40\\%$ and then also miscalculating. The distractor $\\$87.50$ results from treating the markup and discount as additive ($40\\% - 15\\% = 25\\%$, then $70 \\times 1.25 = 87.50$). The distractor $\\$98$ is the retail price before the discount, omitting the discount step entirely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AILQ97', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'A town''s population was $8{,}400$ at the start of 2023. By the start of 2024, the population had increased to $9{,}072$. What was the percent increase in the town''s population from 2023 to 2024?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'The population increase is $9{,}072 - 8{,}400 = 672$. The percent increase is $\\frac{672}{8{,}400} \\times 100 = 8\\%$. A common error is dividing by the new population ($\\frac{672}{9{,}072} \\approx 7.4\\%$), which uses the wrong base for percent change.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ASXUB4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A deck contains 13 red cards, 9 blue cards, and 5 green cards. If one card is selected at random, what is the probability that the card is blue?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{9}{27}\\)"},{"key":"B","text":"\\(\\dfrac{9}{22}\\)"},{"key":"C","text":"\\(\\dfrac{13}{27}\\)"},{"key":"D","text":"\\(\\dfrac{5}{27}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of cards is 13 + 9 + 5 = 27. The probability of selecting a blue card is 9/27, which simplifies to 1/3. The distractor 9/22 results from incorrectly adding the total as 22 instead of 27, an arithmetic slip. The distractor 13/27 uses the count of red cards instead of blue, misreading which color was asked about. The distractor 5/27 uses the count of green cards instead of blue, again misreading the question.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B667Z5', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 5x - 13$. What is the value of $f(7)$?', NULL, $lyceon_json$[{"key":"A","text":"$-6$"},{"key":"B","text":"$4$"},{"key":"C","text":"$22$"},{"key":"D","text":"$48$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substitute $x = 7$: $f(7) = 5(7) - 13 = 35 - 13 = 22$. The value $-6$ results from computing $7 - 13 = -6$, substituting without multiplying by the coefficient. The value $4$ results from solving $5x - 13 = 7$ for $x$ (getting $x = 4$) instead of evaluating $f(7)$. The value $48$ results from computing $5(7) + 13 = 48$, adding instead of subtracting.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BKT37E', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'A community garden charges an annual membership fee of $\\$47$ plus $\\$3$ per square foot of garden bed rented. A gardener has a budget of no more than $\\$200$ for the year. Which inequality represents the number of square feet, $s$, the gardener can rent?', NULL, $lyceon_json$[{"key":"A","text":"$3s + 47 \\leq 200$"},{"key":"B","text":"$3s + 47 \\geq 200$"},{"key":"C","text":"$47s + 3 \\leq 200$"},{"key":"D","text":"$3s - 47 \\leq 200$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is the membership fee of $\\$47$ plus $\\$3$ per square foot, giving $3s + 47$. Since the gardener''s budget is no more than $\\$200$, the inequality is $3s + 47 \\leq 200$. The distractor $3s + 47 \\geq 200$ reverses the direction of the inequality, misinterpreting "no more than" as "at least." The distractor $47s + 3 \\leq 200$ swaps the coefficient and constant, assigning the fixed fee as the per-unit rate. The distractor $3s - 47 \\leq 200$ subtracts the membership fee instead of adding it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BL2OHG', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $\\frac{x^2 + 11x + 28}{x^2 - 49}$ for $x \\neq \\pm 7$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{x + 4}{x - 7}$"},{"key":"B","text":"$\\frac{x + 4}{x + 7}$"},{"key":"C","text":"$\\frac{x - 4}{x - 7}$"},{"key":"D","text":"$\\frac{11x + 28}{-49}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor the numerator: $x^2 + 11x + 28 = (x + 4)(x + 7)$, since $4 \\times 7 = 28$ and $4 + 7 = 11$. Factor the denominator as a difference of squares: $x^2 - 49 = (x - 7)(x + 7)$. Canceling the common factor $(x + 7)$ gives $\\frac{x + 4}{x - 7}$. The distractor $\\frac{x + 4}{x + 7}$ results from canceling $(x - 7)$ instead of $(x + 7)$, confusing which factor is shared. The distractor $\\frac{x - 4}{x - 7}$ introduces a sign error in the numerator factorization. The distractor $\\frac{11x + 28}{-49}$ results from incorrectly canceling $x^2$ from numerator and denominator separately.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C1Y2XZ', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $x$-intercept of the line $3x - 7y = 42$?', NULL, $lyceon_json$[{"key":"A","text":"$(6, 0)$"},{"key":"B","text":"$(0, -6)$"},{"key":"C","text":"$(14, 0)$"},{"key":"D","text":"$(0, 14)$"}]$lyceon_json$::jsonb, 'C', NULL, E'To find the $x$-intercept, set $y = 0$: $3x - 7(0) = 42$, so $3x = 42$ and $x = 14$. The $x$-intercept is $(14, 0)$. The point $(6, 0)$ results from dividing $42$ by $7$ instead of $3$, mixing up coefficients. The point $(0, -6)$ is the $y$-intercept ($-7y = 42$, $y = -6$), not the $x$-intercept — a concept confusion. The point $(0, 14)$ places the correct $x$-value at the wrong intercept type.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CCW2PO', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular box has a length of $11$ inches, a width of $6$ inches, and a height of $4$ inches. What is the volume of the box, in cubic inches?', NULL, $lyceon_json$[{"key":"A","text":"$264$"},{"key":"B","text":"$21$"},{"key":"C","text":"$110$"},{"key":"D","text":"$328$"}]$lyceon_json$::jsonb, 'A', NULL, E'The volume of a rectangular box is $V = l \\times w \\times h = 11 \\times 6 \\times 4 = 264$ cubic inches. The value $21$ comes from adding the three dimensions ($11 + 6 + 4 = 21$) instead of multiplying them. The value $110$ results from multiplying only two dimensions: $11 \\times 10 = 110$, likely misreading $6$ as $10$ or computing a face area instead. The value $328$ comes from computing the surface area $2(11 \\times 6 + 11 \\times 4 + 6 \\times 4) = 2(66 + 44 + 24) = 2(134) = 268$ and then adding an extra $60$, or from a different arithmetic error in the multiplication.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D4QRZH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A right triangular prism has a base that is a right triangle with legs of length $9$ cm and $14$ cm. The prism has a height of $20$ cm. A plane cuts the prism parallel to the triangular bases, $8$ cm from one end. What is the volume, in cubic centimeters, of the smaller piece created by this cut?', NULL, $lyceon_json$[{"key":"A","text":"$504$"},{"key":"B","text":"$1260$"},{"key":"C","text":"$630$"},{"key":"D","text":"$1008$"}]$lyceon_json$::jsonb, 'A', NULL, E'The triangular base has area $\\frac{1}{2}(9)(14) = 63$ square cm. Since the cut is parallel to the base, the cross-sectional area remains $63$ square cm throughout. The smaller piece has height $8$ cm (the shorter of the two segments when a $20$ cm prism is cut $8$ cm from one end), so its volume is $63 \\times 8 = 504$ cubic cm. The value $1260$ is the volume of the entire prism ($63 \\times 20$), answering the wrong question. The value $630$ is half the total volume ($1260 \\div 2$), as though the cut were at the midpoint. The value $1008$ results from forgetting the $\\frac{1}{2}$ factor in the triangle area formula: $9 \\times 14 \\times 8 = 1008$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D71FLK', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'What is the value of $x$ in the equation $$\\frac{3(2x - 5)}{4} + 7 = \\frac{x + 13}{2}\\,?$$', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13/4', ARRAY['13/4', '3.25'], E'Multiply every term by $4$ to eliminate fractions: $3(2x - 5) + 28 = 2(x + 13)$. Distribute: $6x - 15 + 28 = 2x + 26$, which simplifies to $6x + 13 = 2x + 26$. Subtract $2x$ from both sides: $4x + 13 = 26$. Subtract $13$: $4x = 13$. Divide by $4$: $x = \\frac{13}{4}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DMB6X4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A health researcher observes that people who drink herbal tea daily have lower blood pressure on average than people who do not drink herbal tea. Which of the following is a valid conclusion from this observational study?', NULL, $lyceon_json$[{"key":"A","text":"There is an association between drinking herbal tea daily and lower blood pressure."},{"key":"B","text":"Drinking herbal tea daily causes lower blood pressure."},{"key":"C","text":"People who stop drinking herbal tea will experience higher blood pressure."},{"key":"D","text":"Herbal tea lowers blood pressure more effectively than medication."}]$lyceon_json$::jsonb, 'A', NULL, E'An observational study can identify an association between variables but cannot establish causation because subjects are not randomly assigned to treatment and control groups. The distractor claiming herbal tea causes lower blood pressure incorrectly draws a causal conclusion from an observational study. The distractor about stopping herbal tea leading to higher blood pressure also implies causation and makes a predictive claim not supported by an observational design. The distractor comparing herbal tea to medication introduces a comparison that was never part of the study, misreading what was measured.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E1KU4X', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A researcher wants to determine whether a new fertilizer increases tomato yield. She selects 80 tomato plants and randomly assigns 40 to receive the new fertilizer and 40 to receive a standard fertilizer. At the end of the growing season, the plants receiving the new fertilizer produced an average of 11.3 pounds of tomatoes compared to 8.7 pounds for the standard fertilizer group. Which of the following best describes why this study can support a causal conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Random assignment of plants to treatment groups controls for confounding variables."},{"key":"B","text":"The sample size of 80 plants is large enough to represent all tomato varieties."},{"key":"C","text":"The researcher measured a quantitative outcome rather than a qualitative one."},{"key":"D","text":"Both groups received some type of fertilizer, ensuring fairness."}]$lyceon_json$::jsonb, 'A', NULL, E'Random assignment is what allows an experiment to support causal conclusions. By randomly assigning plants to treatment and control groups, the researcher ensures that other variables (soil quality, sunlight, genetics) are balanced across groups, so any observed difference in yield can be attributed to the fertilizer. The distractor about sample size representing all tomato varieties confuses sample size with generalizability — random assignment controls confounding, while random selection from a broad population supports generalizability. The distractor about quantitative outcomes describes a measurement choice unrelated to establishing causation. The distractor about both groups receiving fertilizer describes a design detail that does not explain why causation can be inferred; it is random assignment, not the presence of a control treatment, that is the key feature.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EEB6JP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Two parallel lines are cut by a transversal. One of the angles formed measures $(7x + 11)°$ and a co-interior (same-side interior) angle measures $(4x + 29)°$. What is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{140}{11}$"},{"key":"B","text":"$\\frac{18}{3}$"},{"key":"C","text":"$\\frac{40}{11}$"},{"key":"D","text":"$\\frac{169}{11}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Co-interior angles formed by parallel lines and a transversal are supplementary, so $(7x + 11) + (4x + 29) = 180$. This simplifies to $11x + 40 = 180$, giving $11x = 140$ and $x = \\frac{140}{11}$. The value $\\frac{18}{3} = 6$ results from incorrectly setting the angles equal (as if they were alternate interior angles): $7x + 11 = 4x + 29$, yielding $3x = 18$ and $x = 6$. The value $\\frac{40}{11}$ comes from the supplementary setup but solving $11x = 40$ instead of $11x = 140$, dropping the $180$ and solving $11x + 40 = 80$ or a similar subtraction error. The value $\\frac{169}{11}$ results from adding the constants incorrectly: $11x = 180 - 11 = 169$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EMQJST', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'Two sections of a statistics class took the same test. Section X has $18$ students with a mean score of $74$. Section Y has $12$ students with a mean score of $86$. A student claims that the overall mean score for both sections combined is $80$. Which of the following best explains why the student''s claim is incorrect?', NULL, $lyceon_json$[{"key":"A","text":"The overall mean is $78.8$ because the combined mean must be weighted by the number of students in each section."},{"key":"B","text":"The overall mean is $82$ because the median of $74$ and $86$ should be used instead of the mean."},{"key":"C","text":"The overall mean is $80$ and the student's claim is correct because averaging $74$ and $86$ gives $80$."},{"key":"D","text":"The overall mean cannot be determined without knowing each individual student's score."}]$lyceon_json$::jsonb, 'A', NULL, E'The weighted mean is $\\frac{18 \\times 74 + 12 \\times 86}{18 + 12} = \\frac{1332 + 1032}{30} = \\frac{2364}{30} = 78.8$. Since Section X has more students, the combined mean is pulled toward $74$, not the simple average of the two means. The option stating the overall mean is $78.8$ because it must be weighted by class size is correct. The option claiming $82$ confuses median with weighted mean and arrives at an incorrect value. The option claiming $80$ makes the error of treating the two means equally regardless of group size. The option claiming the mean cannot be determined is wrong because the section means and sizes are sufficient to compute the combined mean.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G29KJ1', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $\\ell$ passes through the point $(2, 7)$ and is perpendicular to the line $5x - 3y = 18$. What is the $y$-intercept of line $\\ell$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{11}{3}$"},{"key":"B","text":"$\\frac{29}{5}$"},{"key":"C","text":"$\\frac{41}{5}$"},{"key":"D","text":"$\\frac{31}{3}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Rewrite $5x - 3y = 18$ in slope-intercept form: $y = \\frac{5}{3}x - 6$, so the slope is $\\frac{5}{3}$. The perpendicular slope is $-\\frac{3}{5}$. Using point-slope form with $(2, 7)$: $y - 7 = -\\frac{3}{5}(x - 2)$, which gives $y = -\\frac{3}{5}x + \\frac{6}{5} + 7 = -\\frac{3}{5}x + \\frac{41}{5}$. The $y$-intercept is $\\frac{41}{5}$. The value $\\frac{11}{3}$ results from using the original slope $\\frac{5}{3}$ instead of the perpendicular slope: $y - 7 = \\frac{5}{3}(x - 2)$ yields $y$-intercept $\\frac{11}{3}$. The value $\\frac{29}{5}$ results from using the reciprocal $\\frac{3}{5}$ without negating: $y - 7 = \\frac{3}{5}(x - 2)$ yields $y$-intercept $\\frac{29}{5}$. The value $\\frac{31}{3}$ results from negating the slope to $-\\frac{5}{3}$ without taking the reciprocal: $y - 7 = -\\frac{5}{3}(x - 2)$ yields $y$-intercept $\\frac{31}{3}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IJGAE9', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'$$\\begin{cases} 5x - 3y = 17 \\\\ 2x + 3y = 11 \\end{cases}$$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IL2VHR', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'A circle in the $xy$-plane has the equation $$x^2 + y^2 - 10x + 4y - 71 = 0.$$ What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '10', ARRAY['10'], E'Complete the square for both variables. Group terms: $(x^2 - 10x) + (y^2 + 4y) = 71$. For $x$: half of $-10$ is $-5$, and $(-5)^2 = 25$, so $(x^2 - 10x + 25) = (x - 5)^2$; add $25$ to the right side. For $y$: half of $4$ is $2$, and $2^2 = 4$, so $(y^2 + 4y + 4) = (y + 2)^2$; add $4$ to the right side. The equation becomes $(x - 5)^2 + (y + 2)^2 = 71 + 25 + 4 = 100$. The radius is $\\sqrt{100} = 10$. A common error is forgetting to add the completing-the-square constants to the right side, giving $r = \\sqrt{71} \\approx 8.43$. Another error is computing $71 + 25 + 4$ as $96$ (arithmetic slip), yielding $r = \\sqrt{96}$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IRP2D6', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'The linear function $h$ satisfies $h(2) = 19$ and $h(7) = 54$. What is the value of $h(-1)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-2', ARRAY['-2'], E'First, find the slope: $m = \\frac{54 - 19}{7 - 2} = \\frac{35}{5} = 7$. Using the point $(2, 19)$: $19 = 7(2) + b$, so $b = 19 - 14 = 5$. Thus $h(x) = 7x + 5$. Evaluating at $x = -1$: $h(-1) = 7(-1) + 5 = -7 + 5 = -2$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
