INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IZTGWF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'A data set contains $7$ values. Six of the values are $14, 23, 19, 31, 27, 22$. If the mean of all $7$ values is $23$, what is the $7$th value?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '25', ARRAY['25'], E'The sum of all $7$ values must equal $23 \\times 7 = 161$. The sum of the six known values is $14 + 23 + 19 + 31 + 27 + 22 = 136$. Therefore the $7$th value is $161 - 136 = 25$. A common error is computing the mean of the six known values ($136 \\div 6 \\approx 22.67$) and subtracting from $23$, which gives the wrong answer.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JKL80L', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'In a class of 150 students, 42 study French, 63 study Spanish, and 18 study both French and Spanish. If a student is selected at random and it is known that the student studies Spanish, what is the probability that the student also studies French?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{18}{63}\\)"},{"key":"B","text":"\\(\\dfrac{18}{150}\\)"},{"key":"C","text":"\\(\\dfrac{42}{150}\\)"},{"key":"D","text":"\\(\\dfrac{18}{42}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'This is a conditional probability question. P(French | Spanish) = P(French and Spanish) / P(Spanish) = 18/63, which simplifies to 2/7. The distractor 18/150 divides by the total number of students rather than the number of Spanish students, showing a concept gap about conditional versus unconditional probability. The distractor 42/150 gives the overall probability of studying French, misreading the question by ignoring the condition that the student studies Spanish. The distractor 18/42 divides the overlap by the number of French students instead of Spanish students, reversing the conditioning event.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KBGZJ5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $ABC$, side $AB = 19$, side $BC = 23$, and side $AC = 14$. A line segment $DE$ is drawn parallel to $BC$ where $D$ is on $AB$ and $E$ is on $AC$, such that $AD = 7$. What is the length of $DE$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '161/19', ARRAY['8.473', '8.474'], E'Since $DE \\parallel BC$, triangle $ADE$ is similar to triangle $ABC$ by the AA similarity criterion. The ratio of similarity is $\\frac{AD}{AB} = \\frac{7}{19}$. Therefore $DE = BC \\times \\frac{7}{19} = 23 \\times \\frac{7}{19} = \\frac{161}{19}$. A common error is using $\\frac{AD}{DB} = \\frac{7}{12}$ as the similarity ratio instead of $\\frac{AD}{AB}$, which would give $DE = 23 \\times \\frac{7}{12} = \\frac{161}{12}$. Another error is computing $DE$ as the difference $23 - 7 = 16$ by confusing the parallel segment length with subtraction of sides.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KCMSUD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A student recorded the following quiz scores: $71, 84, 77, 91, 82$. What is the median of these scores?', NULL, $lyceon_json$[{"key":"A","text":"$77$"},{"key":"B","text":"$81$"},{"key":"C","text":"$82$"},{"key":"D","text":"$84$"}]$lyceon_json$::jsonb, 'C', NULL, E'Arranging the scores in order: $71, 77, 82, 84, 91$. With $5$ values, the median is the $3$rd value, which is $82$. The distractor $77$ is the $2$nd value in the ordered list, chosen if the student picks the wrong position. The distractor $81$ results from averaging all five values ($\\frac{405}{5} = 81$), confusing mean with median. The distractor $84$ is the $4$th value, selected by miscounting the middle position.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L4DU3J', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $(3x - 8)(4x + 5)$?', NULL, $lyceon_json$[{"key":"A","text":"$12x^2 - 17x - 40$"},{"key":"B","text":"$12x^2 + 47x - 40$"},{"key":"C","text":"$12x^2 - 17x + 40$"},{"key":"D","text":"$12x^2 - 47x - 40$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using the distributive property (FOIL): $(3x)(4x) = 12x^2$, $(3x)(5) = 15x$, $(-8)(4x) = -32x$, and $(-8)(5) = -40$. Combining: $12x^2 + 15x - 32x - 40 = 12x^2 - 17x - 40$. The distractor $12x^2 + 47x - 40$ results from treating both middle terms as positive ($15x + 32x$). The distractor $12x^2 - 17x + 40$ applies a sign error to the constant, treating $(-8)(5)$ as $+40$. The distractor $12x^2 - 47x - 40$ results from treating both middle terms as negative ($-15x - 32x$).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LP22BP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 400 voters in a city found that 53% support a proposed park renovation. The margin of error for the survey is 4 percentage points. Which of the following is the best interpretation of the margin of error?', NULL, $lyceon_json$[{"key":"A","text":"It is plausible that between 49% and 57% of all voters in the city support the park renovation."},{"key":"B","text":"Exactly 53% of all voters in the city support the park renovation."},{"key":"C","text":"Between 49% and 57% of the 400 sampled voters support the park renovation."},{"key":"D","text":"4% of the voters surveyed did not respond to the question."}]$lyceon_json$::jsonb, 'A', NULL, E'The margin of error means the true population proportion is plausibly within 4 percentage points of the sample proportion, so between 49% and 57%. The distractor stating exactly 53% ignores that the sample statistic is an estimate of the population parameter, not the exact value. The distractor applying the interval to the sample rather than the population confuses the sample (which is known) with the population (which is estimated). The distractor interpreting margin of error as a nonresponse rate misreads what margin of error means.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MF35FD', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A swimming pool is being drained. The volume of water remaining, in gallons, can be modeled by the function $w(t) = -37t + 1{,}850$, where $t$ is the number of minutes since draining began. Which of the following is the best interpretation of the number $37$ in this context?', NULL, $lyceon_json$[{"key":"A","text":"The initial volume of water in the pool is $37$ gallons."},{"key":"B","text":"The pool loses $37$ gallons of water per minute."},{"key":"C","text":"The pool will be completely empty after $37$ minutes."},{"key":"D","text":"The total amount of water drained from the pool is $37$ gallons."}]$lyceon_json$::jsonb, 'B', NULL, E'In the function $w(t) = -37t + 1{,}850$, the coefficient $-37$ is the rate of change — the pool loses $37$ gallons per minute. The initial volume interpretation confuses the slope with the $y$-intercept; the initial volume is $1{,}850$ gallons (the value when $t = 0$). The claim that the pool empties after $37$ minutes confuses the coefficient with the solution to $w(t) = 0$; the pool empties at $t = 50$ minutes. The claim that $37$ gallons is the total drained confuses a rate (gallons per minute) with a cumulative total.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N5MC5B', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f(x) = a(x - h)^2 + k$ has its vertex at $(4, -3)$ and passes through the point $(7, 15)$. What is the value of $a$?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$3$"},{"key":"C","text":"$-2$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'A', NULL, E'Since the vertex is $(4, -3)$, the function is $f(x) = a(x - 4)^2 - 3$. Substituting the point $(7, 15)$: $15 = a(7 - 4)^2 - 3 = 9a - 3$. Solving: $9a = 18$, so $a = 2$. The distractor $a = 3$ results from computing $(7 - 4)^2 = 6$ instead of $9$, then solving $6a = 18$. The distractor $a = -2$ applies a sign error, treating the equation as $9a + 3 = -15$. The distractor $a = 6$ results from forgetting to square the difference, computing $a(3) - 3 = 15$ to get $3a = 18$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NBT904', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The polynomial function $f$ is defined by $f(x) = x^3 - 9x^2 + 23x - 15$. If $f(1) = 0$, which of the following gives all zeros of $f$?', NULL, $lyceon_json$[{"key":"A","text":"$1$, $3$, and $5$"},{"key":"B","text":"$1$, $-3$, and $5$"},{"key":"C","text":"$1$, $3$, and $-5$"},{"key":"D","text":"$-1$, $3$, and $5$"}]$lyceon_json$::jsonb, 'A', NULL, E'Since $f(1) = 0$, $(x - 1)$ is a factor. Performing polynomial division: $x^3 - 9x^2 + 23x - 15 = (x - 1)(x^2 - 8x + 15)$. Factoring the quadratic: $x^2 - 8x + 15 = (x - 3)(x - 5)$, since $(-3)(-5) = 15$ and $(-3) + (-5) = -8$. Therefore the zeros are $1$, $3$, and $5$. The distractor $1$, $-3$, and $5$ introduces a sign error on the middle zero, treating the factor as $(x + 3)$. The distractor $1$, $3$, and $-5$ applies a sign error to the largest zero. The distractor $-1$, $3$, and $5$ flips the sign of the given zero, contradicting the stated condition $f(1) = 0$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PCQT6X', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'The system of equations below has no solution. What is the value of the constant $k$?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PH37I1', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $47°$ and the measure of angle $Q$ is $86°$. What is the measure, in degrees, of angle $R$?', NULL, $lyceon_json$[{"key":"A","text":"$37°$"},{"key":"B","text":"$43°$"},{"key":"C","text":"$47°$"},{"key":"D","text":"$57°$"}]$lyceon_json$::jsonb, 'C', NULL, E'The sum of the interior angles of a triangle is $180°$. Thus angle $R = 180° - 47° - 86° = 47°$. The value $37°$ results from a subtraction error when computing $180 - 143$. The value $43°$ comes from incorrectly halving $86°$ and treating the result as the remaining angle. The value $57°$ results from misapplying supplementary angles, computing $180 - 47 - 86$ as $180 - 123 = 57$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QIU5U8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of 200 students found that 74 play soccer, 58 play tennis, and 23 play both soccer and tennis. If a student is chosen at random from the survey, what is the probability that the student plays soccer or tennis?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{109}{200}\\)"},{"key":"B","text":"\\(\\dfrac{132}{200}\\)"},{"key":"C","text":"\\(\\dfrac{74}{200}\\)"},{"key":"D","text":"\\(\\dfrac{155}{200}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Using the inclusion-exclusion principle, P(soccer or tennis) = (74 + 58 − 23)/200 = 109/200. The distractor 132/200 adds 74 + 58 = 132 without subtracting the 23 students who play both, reflecting a concept gap about inclusion-exclusion. The distractor 74/200 considers only soccer players, using partial reasoning that ignores tennis entirely. The distractor 155/200 results from adding 74 + 58 + 23 = 155, incorrectly adding the overlap instead of subtracting it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QQJ93L', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A line of best fit for a scatterplot is given by $y = 2.1x + 14$. What does the model predict for $y$ when $x = 10$?', NULL, $lyceon_json$[{"key":"A","text":"$16.1$"},{"key":"B","text":"$24$"},{"key":"C","text":"$35$"},{"key":"D","text":"$210$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 10$: $y = 2.1(10) + 14 = 21 + 14 = 35$. The distractor $16.1$ comes from adding $2.1 + 14 = 16.1$, effectively substituting $x = 1$ instead of $x = 10$. The distractor $24$ results from computing $10 + 14 = 24$, ignoring the slope coefficient entirely. The distractor $210$ comes from computing $2.1 \\times 10 \\times 10 = 210$, squaring the input instead of using the linear model.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R8OZPJ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'What is the solution to $\\sqrt{5x + 11} = x + 1$?', NULL, $lyceon_json$[{"key":"A","text":"$x = -2$ only"},{"key":"B","text":"$x = 5$ only"},{"key":"C","text":"$x = -2$ and $x = 5$"},{"key":"D","text":"$x = 3$ only"}]$lyceon_json$::jsonb, 'B', NULL, E'Square both sides: $5x + 11 = (x + 1)^2 = x^2 + 2x + 1$. Rearrange: $x^2 - 3x - 10 = 0$, which factors as $(x - 5)(x + 2) = 0$, giving $x = 5$ or $x = -2$. Check $x = 5$: $\\sqrt{5(5) + 11} = \\sqrt{36} = 6$ and $5 + 1 = 6$ ✓. Check $x = -2$: $\\sqrt{5(-2) + 11} = \\sqrt{1} = 1$ but $-2 + 1 = -1 \\neq 1$ ✗. So $x = -2$ is extraneous and the only solution is $x = 5$. The distractor $x = -2$ only selects the extraneous root. The distractor listing both values fails to check for extraneous solutions. The distractor $x = 3$ results from an arithmetic error in the quadratic.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RKTF9O', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'A phone company offers two plans. Plan X charges a monthly fee of $\\$31$ plus $\\$0.07$ per text message. Plan Y charges a monthly fee of $\\$19$ plus $\\$0.11$ per text message. For what number of text messages in a month would the total cost of Plan X exceed the total cost of Plan Y by exactly $\\$4.80$?', NULL, $lyceon_json$[{"key":"A","text":"$120$"},{"key":"B","text":"$180$"},{"key":"C","text":"$300$"},{"key":"D","text":"$420$"}]$lyceon_json$::jsonb, 'B', NULL, E'Set up the equation $(31 + 0.07t) - (19 + 0.11t) = 4.80$. Simplify the left side: $12 - 0.04t = 4.80$. Subtract $12$: $-0.04t = -7.20$. Divide by $-0.04$: $t = 180$. The value $120$ comes from computing $\\frac{4.80}{0.04} = 120$ while ignoring the $\\$12$ difference in base fees — a partial-reasoning error. The value $300$ comes from setting the two plan costs equal ($31 + 0.07t = 19 + 0.11t$) and solving $12 = 0.04t$, which finds where costs are equal rather than where they differ by $\\$4.80$. The value $420$ comes from reversing the subtraction order, computing $(19 + 0.11t) - (31 + 0.07t) = 4.80$, which yields $0.04t - 12 = 4.80$ and $t = 420$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RNF4KR', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'The system of equations $y = x^2 - 5x + 3$ and $y = 2x - 9$ has two solutions. What is the sum of the $x$-coordinates of these two solutions?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Setting the expressions equal: $x^2 - 5x + 3 = 2x - 9$. Rearranging: $x^2 - 7x + 12 = 0$. Factoring: $(x - 3)(x - 4) = 0$, so $x = 3$ or $x = 4$. The sum of the $x$-coordinates is $3 + 4 = 7$. Alternatively, by Vieta''s formulas, the sum of roots of $x^2 - 7x + 12 = 0$ is $7$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RTJWRW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'grid_in', E'A printer produces $37$ pages in $4$ minutes. At this constant rate, how many minutes will it take to print $259$ pages?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '28', ARRAY['28'], E'The printer''s rate is $\\frac{37 \\text{ pages}}{4 \\text{ minutes}}$. To find the time for $259$ pages: $\\frac{259}{37} = 7$, so $259$ pages requires $7$ times as long as $37$ pages. Therefore $7 \\times 4 = 28$ minutes.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RUACQ2', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples are taken from the same population of 8,500 registered voters. Sample A surveys 250 voters and finds 44% favor a bond measure, with a margin of error of 6.2 percentage points. Sample B surveys 1,000 voters and finds 41% favor the bond measure, with a margin of error of 3.1 percentage points. Which of the following statements is best supported by the information given?', NULL, $lyceon_json$[{"key":"A","text":"Sample B's confidence interval is more likely to contain the true population proportion because its margin of error is smaller."},{"key":"B","text":"Sample A is more reliable because it found a higher percentage in favor of the bond measure."},{"key":"C","text":"The two samples prove that between 41% and 44% of the population favors the bond measure."},{"key":"D","text":"The difference between the two sample proportions proves the survey method is biased."}]$lyceon_json$::jsonb, 'A', NULL, E'A larger sample size produces a smaller margin of error, giving a narrower confidence interval that is more precise. Sample B, with 1,000 voters and a 3.1 percentage point margin of error, provides a more precise estimate than Sample A. The distractor claiming Sample A is more reliable because of a higher percentage confuses the magnitude of a sample statistic with the precision of the estimate. The distractor claiming the samples prove the proportion is between 41% and 44% misuses the word prove — samples provide estimates, not certainties, and the confidence intervals overlap substantially. The distractor claiming the difference proves bias confuses natural sampling variability with systematic bias.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RURON6', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $3x^2 + 7x - 2x^2 + 4x - 11$?', NULL, $lyceon_json$[{"key":"A","text":"$x^2 + 11x - 11$"},{"key":"B","text":"$5x^2 + 11x - 11$"},{"key":"C","text":"$x^2 + 3x - 11$"},{"key":"D","text":"$x^2 + 11x + 11$"}]$lyceon_json$::jsonb, 'A', NULL, E'Combining like terms: the $x^2$ terms give $3x^2 - 2x^2 = x^2$, the $x$ terms give $7x + 4x = 11x$, and the constant is $-11$, yielding $x^2 + 11x - 11$. The distractor $5x^2 + 11x - 11$ results from adding the $x^2$ coefficients ($3 + 2$) instead of subtracting. The distractor $x^2 + 3x - 11$ results from subtracting the $x$ coefficients ($7 - 4$) instead of adding. The distractor $x^2 + 11x + 11$ applies a sign error to the constant term.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UH33ZC', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'grid_in', E'The function $f$ is defined by $f(x) = x^2 + 14x + 53$. What is the minimum value of $f(x)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Completing the square: $f(x) = x^2 + 14x + 53 = (x^2 + 14x + 49) + 4 = (x + 7)^2 + 4$. Since $(x + 7)^2 \\geq 0$ for all real $x$, the minimum value of $f(x)$ is $0 + 4 = 4$, occurring at $x = -7$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WL44BH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A scatterplot shows the relationship between the number of years since a company was founded ($x$) and its annual revenue in thousands of dollars ($y$). The line of best fit is $y = 4.7x + 31$. Which of the following is the best interpretation of the slope of this line?', NULL, $lyceon_json$[{"key":"A","text":"The company's revenue is predicted to increase by $\\$4{,}700$ each year."},{"key":"B","text":"The company's revenue is predicted to increase by $\\$4.70$ each year."},{"key":"C","text":"The company's initial revenue when it was founded was $\\$4{,}700$."},{"key":"D","text":"For every $\\$1{,}000$ increase in revenue, the company ages by $4.7$ years."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope $4.7$ means that for each additional year, the predicted revenue increases by $4.7$ thousand dollars, which is $\\$4{,}700$. The distractor stating $\\$4.70$ ignores that $y$ is measured in thousands of dollars, a unit error. The distractor claiming $\\$4{,}700$ is the initial revenue confuses the slope with the $y$-intercept; the $y$-intercept is $31$ thousand, or $\\$31{,}000$. The distractor reversing the variables misinterprets the slope as the change in $x$ per unit change in $y$, inverting the relationship.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"unit_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WMPPR1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A university study tracks 1,200 students over four years and finds that students who regularly attend office hours earn GPAs that are, on average, 0.4 points higher than students who do not attend office hours. A newspaper headline reports: "Attending office hours boosts GPA by 0.4 points." Which of the following best explains why the headline''s claim is not justified by the study?', NULL, $lyceon_json$[{"key":"A","text":"The study is observational, so the difference in GPA could be due to confounding variables such as motivation or study habits rather than office hours attendance itself."},{"key":"B","text":"The study did not include students from other universities, so the margin of error is too large."},{"key":"C","text":"A 0.4-point GPA difference is too small to be statistically significant with a sample of 1,200 students."},{"key":"D","text":"The study should have used a median GPA instead of a mean GPA to avoid the effect of outliers."}]$lyceon_json$::jsonb, 'A', NULL, E'The study is observational — students self-selected into attending or not attending office hours. Students who attend office hours may differ systematically from those who do not in ways that also affect GPA, such as higher motivation, stronger study habits, or more engagement with coursework. These confounding variables make it impossible to conclude that office hours attendance itself caused the GPA increase. The distractor about excluding other universities addresses generalizability, not the causal claim — even a perfectly generalizable observational study cannot establish causation. The distractor claiming 0.4 points is too small to be significant is incorrect because with 1,200 students, even modest differences can be statistically significant; furthermore, statistical significance is different from causation. The distractor about median versus mean addresses a choice of summary statistic that does not resolve the fundamental issue of confounding in an observational design.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y0ELHC', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'A car rental company charges $\\$26$ per day plus a one-time insurance fee of $\\$52$. If the total cost of a rental was $\\$182$, for how many days was the car rented?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$5$"},{"key":"C","text":"$7$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total cost equation is $26d + 52 = 182$. Subtracting $52$ from both sides gives $26d = 130$, so $d = 5$. The answer $7$ results from dividing the total $182$ by $26$ without subtracting the insurance fee. The answer $9$ results from adding the insurance fee to the total ($182 + 52 = 234$) and then dividing by $26$, reversing the subtraction step. The answer $4$ results from a computational error when dividing $130$ by $26$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YJNEAM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'A surveyor stands at point $A$ and measures the angle of elevation to the top of a building at point $B$ as $31°$. She then walks $42$ meters directly toward the building to point $C$, where the angle of elevation to the top is $53°$. Which of the following expressions gives the height of the building, in meters?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{42\\sin(31°)\\sin(53°)}{\\sin(22°)}$"},{"key":"B","text":"$\\frac{42\\tan(31°)\\tan(53°)}{\\tan(53°) - \\tan(31°)}$"},{"key":"C","text":"$\\frac{42\\sin(31°)}{\\sin(53°)}$"},{"key":"D","text":"$\\frac{42}{\\tan(53°) + \\tan(31°)}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $h$ be the height and $d$ the horizontal distance from point $C$ to the base. Then $\\tan(53°) = \\frac{h}{d}$ and $\\tan(31°) = \\frac{h}{d + 42}$. Solving for $d$: $d = \\frac{h}{\\tan(53°)}$ and $d + 42 = \\frac{h}{\\tan(31°)}$. Subtracting gives $42 = \\frac{h}{\\tan(31°)} - \\frac{h}{\\tan(53°)} = h \\cdot \\frac{\\tan(53°) - \\tan(31°)}{\\tan(31°)\\tan(53°)}$. Solving for $h$ yields $h = \\frac{42\\tan(31°)\\tan(53°)}{\\tan(53°) - \\tan(31°)}$. The expression with $\\sin(22°)$ in the denominator incorrectly applies the law of sines to a triangle that does not match the geometry of the problem. The expression $\\frac{42\\sin(31°)}{\\sin(53°)}$ only partially sets up the relationship and ignores the second distance equation. The expression with $\\tan(53°) + \\tan(31°)$ in the denominator uses addition instead of subtraction, reversing the sign when eliminating $d$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YW616P', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'$$\\begin{cases} x + y = 19 \\\\ x - y = 5 \\end{cases}$$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZX3Z59', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A bookstore sells a journal for $\\$24$. During a sale, the price is reduced by $25\\%$. What is the sale price of the journal?', NULL, $lyceon_json$[{"key":"A","text":"$\\$6$"},{"key":"B","text":"$\\$16$"},{"key":"C","text":"$\\$18$"},{"key":"D","text":"$\\$19$"}]$lyceon_json$::jsonb, 'C', NULL, E'A $25\\%$ discount on $\\$24$ is $0.25 \\times 24 = \\$6$. The sale price is $24 - 6 = \\$18$. The distractor $\\$6$ is the discount amount itself, not the sale price. The distractor $\\$16$ results from subtracting $8$ instead of $6$, as if computing $\\frac{1}{3}$ of $24$. The distractor $\\$19$ comes from a miscalculation yielding a $\\$5$ discount instead of $\\$6$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2020LCZ', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does "temper" most nearly mean?', E'The documentary''s director chose to temper her portrayal of the controversial mining operation by including interviews with both displaced farmers and company engineers who had designed new water filtration systems for the surrounding villages.', $lyceon_json$[{"key":"A","text":"abandon"},{"key":"B","text":"dramatize"},{"key":"C","text":"moderate"},{"key":"D","text":"postpone"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage describes the director including multiple perspectives—displaced farmers and company engineers—to present a balanced portrayal. "Temper" in this context means to moderate or make less extreme, which matches the idea of balancing a controversial subject with opposing viewpoints. "Abandon" is wrong because nothing in the passage suggests the director gave up the portrayal. "Dramatize" is wrong because it means to make more sensational, which is the opposite of what including balanced perspectives achieves. "Postpone" is wrong because it means to delay to a later time, which has no connection to the act of balancing a documentary''s perspective.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW203PPYM', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the text?', E'The axolotl, a salamander native to Lake Xochimilco in central Mexico, can regenerate entire limbs, portions of its spinal cord, and even sections of its heart and brain. Unlike most amphibians, which undergo metamorphosis and transition to land-dwelling adult forms, the axolotl retains its larval features—including external gills and a flattened tail fin—throughout its life, a phenomenon known as neoteny.', $lyceon_json$[{"key":"A","text":"It describes distinctive biological traits of a particular amphibian species."},{"key":"B","text":"It argues that axolotl conservation efforts in Mexico have been insufficient."},{"key":"C","text":"It compares the regenerative abilities of several amphibian species."},{"key":"D","text":"It explains the process by which amphibians undergo metamorphosis."}]$lyceon_json$::jsonb, 'A', NULL, E'The text introduces the axolotl and describes two notable biological traits: its regenerative capacity and its retention of larval features (neoteny). The function is descriptive and focused on a single species. The claim about insufficient conservation efforts is wrong because the passage never discusses conservation policy or its adequacy. The comparison of several species'' regenerative abilities is wrong because only the axolotl''s regeneration is discussed; other amphibians are mentioned only to contrast their metamorphosis. The explanation of metamorphosis is wrong because metamorphosis is referenced only briefly as something the axolotl does not undergo, not as the text''s primary subject.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20F03JT', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Geomorphologist Tanya Atwater''s 1970 paper on plate tectonics in the northeastern Pacific resolved numerous puzzles about the San Andreas Fault system. Her model demonstrated that the fault arose from the interaction between the Pacific and North American plates as the Farallon Plate subducted. ________ her framework implied that the fault is not a single fracture but a wide zone of deformation, a prediction that field geologists subsequently confirmed through GPS measurements across the Coast Ranges.', $lyceon_json$[{"key":"A","text":"Specifically,"},{"key":"B","text":"In other words,"},{"key":"C","text":"On the contrary,"},{"key":"D","text":"Granted,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence before the blank introduces Atwater''s general model of the San Andreas Fault''s origin. The sentence after the blank narrows to a particular implication of that model: that the fault is a wide zone of deformation. This is a general-to-specific elaboration, so the transition meaning ''more precisely'' or ''in particular'' is correct. ''In other words'' wrongly implies a restatement of the same idea rather than an additional specific detail. ''On the contrary'' wrongly signals opposition to the preceding claim. ''Granted'' wrongly signals a concession to a counterargument.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20K7LSY', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'In 2019, marine biologist Yara Nascimento published a study documenting an unexpected finding: populations of the nudibranch Glaucus atlanticus, a small sea slug that floats on the ocean surface, had expanded their range nearly 1,400 kilometers southward along the Brazilian coast over a seven-year period. Nascimento attributed this shift primarily to rising sea surface temperatures, which had made previously inhospitable southern waters warm enough for the species to survive. Her team''s data showed that the slugs'' new range closely tracked isothermal lines that had themselves shifted southward during the same period.', $lyceon_json$[{"key":"A","text":"A marine biologist found that a species of sea slug expanded its range significantly southward, likely due to warming ocean temperatures."},{"key":"B","text":"Glaucus atlanticus is a unique species because it is one of the few sea slugs capable of floating on the ocean surface."},{"key":"C","text":"Rising sea surface temperatures along the Brazilian coast have caused widespread disruption to marine food chains."},{"key":"D","text":"Yara Nascimento's research methods were considered controversial by other marine biologists studying the Brazilian coast."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on Nascimento''s finding that the nudibranch Glaucus atlanticus expanded its range approximately 1,400 kilometers southward, with rising sea surface temperatures identified as the primary cause. The option stating that a marine biologist found a sea slug species expanded its range due to warming temperatures accurately captures this central idea. The option about the slug''s floating ability mentions a detail from the passage but does not address the main finding of range expansion. The option about disruption to marine food chains goes beyond anything stated in the passage, which discusses only one species'' range shift. The option about controversial research methods has no basis in the passage, which does not mention any disagreement among scientists.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20L4BGF', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Dr. Miriam Castellanos, whose research on Mesoamerican agroforestry has been cited in over 240 peer-reviewed publications, argues that traditional milpa farming—a system in which maize, beans, and squash are cultivated together—maintains soil nitrogen at levels comparable to those achieved through synthetic ______ her controlled field trials in Oaxaca demonstrated that milpa plots retained 73 percent of their original nitrogen content after eleven consecutive growing seasons without any chemical supplementation.', $lyceon_json$[{"key":"A","text":"fertilizers, her"},{"key":"B","text":"fertilizers; nonetheless, her"},{"key":"C","text":"fertilizers. Her"},{"key":"D","text":"fertilizers; conversely, her"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage contains two independent clauses separated by a long, complex sentence structure with multiple embedded modifiers (an appositive clause beginning with "whose" and an em-dash parenthetical defining milpa farming). A period correctly separates the clause about Castellanos''s argument from the clause about her field trials. Using a comma alone between these independent clauses creates a comma splice. The semicolon with "nonetheless" incorrectly implies that the field trial results contradict or qualify the argument about nitrogen levels, when in fact the trials directly support that argument. The semicolon with "conversely" incorrectly implies an opposite or contrasting relationship, but the field trial data reinforces rather than opposes the claim about milpa farming''s effectiveness.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2649RFT', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does "modulate" most nearly mean?', E'A marine biologist studying cuttlefish observed that these cephalopods can modulate the pigmentation of their skin within fractions of a second, shifting between vivid reds, muted browns, and near-transparent hues to match their surroundings.', $lyceon_json$[{"key":"A","text":"detect"},{"key":"B","text":"adjust"},{"key":"C","text":"conceal"},{"key":"D","text":"disrupt"}]$lyceon_json$::jsonb, 'B', NULL, E'In the passage, the cuttlefish change their skin pigmentation rapidly to match their environment. "Modulate" means to regulate or adjust something, which fits the description of actively shifting between different color states. "Detect" is wrong because it refers to sensing or perceiving, not controlling a change. "Conceal" is wrong because it means to hide entirely, whereas the passage describes active color adjustment, not hiding. "Disrupt" is wrong because it means to interrupt or throw into disorder, the opposite of the controlled variation described.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW273L9YM', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'While mapping migration corridors along the Danube River basin, ornithologist Yuki Tanaka observed that white storks—long considered solitary during transit—frequently formed temporary foraging groups of seven to twelve ______ this gregarious behavior, which contradicted decades of field observations, prompted Tanaka to redesign her study''s methodology entirely.', $lyceon_json$[{"key":"A","text":"twelve, this"},{"key":"B","text":"twelve; nevertheless, this"},{"key":"C","text":"twelve. This"},{"key":"D","text":"twelve; similarly, this"}]$lyceon_json$::jsonb, 'C', NULL, E'Two independent clauses appear here: one describing Tanaka''s observation about stork foraging groups and another explaining how that behavior prompted her to redesign her methodology. A period correctly separates these clauses. Using a comma alone creates a comma splice. The semicolon with "nevertheless" incorrectly signals a concession—it would imply that the behavior prompted a methodology redesign despite something, but the second clause is a natural consequence of the unexpected observation, not a concession. The semicolon with "similarly" incorrectly signals a comparison, but nothing in the first clause establishes a parallel situation for the second clause to resemble.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27XDPYB', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare geological specimens housed in the university''s basement vault ______ more than four hundred items from seventeen countries, including several samples of a high-purity obsidian found only in a single quarry in Armenia.', $lyceon_json$[{"key":"A","text":"include"},{"key":"B","text":"includes"},{"key":"C","text":"are including"},{"key":"D","text":"have included"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is "collection," which is singular. The prepositional phrase "of rare geological specimens" modifies "collection" but does not change its number. A singular subject requires a singular verb form. "Includes" is the singular present-tense form that agrees with "collection." The plural form "include" incorrectly treats "specimens" as the subject. "Are including" uses the plural progressive form, which both fails to agree in number and uses an unnecessary progressive aspect for a state of being. "Have included" uses the plural present-perfect form, which fails to agree in number with the singular subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29TYAWT', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Economist Soren Lindqvist analyzed patent filings across 23 countries over four decades and found that nations which adopted stronger intellectual property protections did not, on average, see an increase in the rate of novel inventions — defined as patents with no citations to prior work in the same technological class. Instead, the rate of incremental patents — those building directly on existing patents — rose sharply after stronger protections were enacted. Lindqvist acknowledges that stronger protections incentivize investment in research, but he contends that the pattern he observed most likely arises because ________', $lyceon_json$[{"key":"A","text":"companies in countries with stronger protections are more likely to file patents in foreign jurisdictions where protections are weaker."},{"key":"B","text":"the financial incentive to protect existing innovations through derivative patents outweighs the riskier pursuit of entirely novel inventions."},{"key":"C","text":"patent offices in countries with stronger protections apply more rigorous standards when evaluating whether an invention qualifies as novel."},{"key":"D","text":"researchers in countries with weaker protections tend to collaborate more frequently across institutional and national boundaries."}]$lyceon_json$::jsonb, 'B', NULL, E'Lindqvist found that stronger protections increased incremental patents but not novel ones, despite acknowledging that protections incentivize research investment. The most logical explanation is that the financial incentive to protect existing innovations through derivative patents outweighs the riskier pursuit of truly novel inventions — this accounts for both the rise in incremental patents and the stagnation of novel ones. The option about filing patents in foreign jurisdictions introduces cross-border behavior not discussed in the passage and does not explain the domestic pattern of more incremental patents. The option about more rigorous patent office standards could explain fewer novel patents being approved but would not explain the sharp rise in incremental patents, and it attributes the pattern to evaluation criteria rather than inventor behavior, which is Lindqvist''s focus. The option about collaboration in weaker-protection countries introduces a comparison not relevant to explaining why stronger protections shift the balance toward incremental innovation within those countries.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 95, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ANK2PQ', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time the archaeological team completed its excavation of the Neolithic settlement near Lake Ohrid in 2023, the researchers ______ more than 2,300 pottery fragments, many bearing decorative motifs consistent with those found at contemporary sites along the Adriatic coast.', $lyceon_json$[{"key":"A","text":"had cataloged"},{"key":"B","text":"have cataloged"},{"key":"C","text":"will have cataloged"},{"key":"D","text":"are cataloging"}]$lyceon_json$::jsonb, 'A', NULL, E'The construction "by the time the team completed" establishes a past time frame and signals that another action was finished before that past moment. The past perfect tense ("had cataloged") correctly indicates an action completed prior to another past event. The present perfect "have cataloged" incorrectly connects a past action to the present moment, conflicting with the established past time frame of 2023. The future perfect "will have cataloged" places the action in the future, contradicting the past-tense context. The present progressive "are cataloging" places the action in the present and ongoing, which is incompatible with the completed past event described.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2B8N5TE', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The grant proposal outlined three primary objectives for the wetland restoration project: removing invasive phragmites from the northern marshland, ______ and establishing a long-term water-quality monitoring program in partnership with the state environmental agency.', $lyceon_json$[{"key":"A","text":"the reintroduction of native cattail species along the eastern shoreline,"},{"key":"B","text":"to reintroduce native cattail species along the eastern shoreline,"},{"key":"C","text":"reintroducing native cattail species along the eastern shoreline,"},{"key":"D","text":"native cattail species were reintroduced along the eastern shoreline,"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence presents a list of three objectives introduced after a colon. The first item uses a gerund phrase ("removing invasive phragmites") and the third item uses a gerund phrase ("establishing a long-term water-quality monitoring program"). Parallel structure requires the second item to also use a gerund phrase. "Reintroducing native cattail species along the eastern shoreline" maintains the gerund pattern. The noun phrase "the reintroduction of" breaks the parallel gerund structure by substituting a nominalization. The infinitive "to reintroduce" breaks the parallel structure by shifting to a different verb form. The finite clause "native cattail species were reintroduced" breaks parallelism by introducing a complete clause with a conjugated verb where the pattern calls for a gerund phrase.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CH54ZA', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Cognitive scientist Luisa Ferreira conducted an experiment in which participants were asked to estimate the weight of identical-looking boxes that differed only in color. Although every box weighed exactly 3.7 kilograms, participants consistently estimated that darker-colored boxes weighed 8 to 12 percent more than lighter-colored boxes. When Ferreira repeated the experiment with participants who were blindfolded and told the color of each box verbally before lifting it, the effect disappeared: estimates did not vary by reported color. Ferreira argues that this result suggests the weight-color illusion depends on ________', $lyceon_json$[{"key":"A","text":"the participants' prior experience with lifting heavy objects of various colors."},{"key":"B","text":"the visual perception of darkness rather than the mere conceptual knowledge that an object is dark-colored."},{"key":"C","text":"cultural associations between dark colors and negative emotional states such as sadness or anxiety."},{"key":"D","text":"the participants' awareness that they are being observed during a scientific experiment."}]$lyceon_json$::jsonb, 'B', NULL, E'The key experimental contrast is between seeing the dark color (where the illusion occurs) and being told the color while blindfolded (where it does not). This directly supports the conclusion that the illusion depends on visual perception of darkness rather than merely knowing an object is dark-colored. The option about prior experience with heavy objects is not addressed by the experiment''s design, which tested visual versus verbal color information, not experience levels. The option about cultural associations with dark colors and negative emotions introduces a claim that goes beyond the evidence; the passage does not discuss emotional states. The option about awareness of being observed describes a general experimental bias (the Hawthorne effect) that would affect both conditions equally and cannot explain why the effect disappeared only when participants were blindfolded.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CNQKCS', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Researchers at the Jodrell Bank Observatory identified a repeating fast radio burst originating from a magnetar in a nearby dwarf ______ challenging the prevailing hypothesis that such signals were produced exclusively by magnetars located in the dense stellar environments of spiral galaxies.', $lyceon_json$[{"key":"A","text":"galaxy, challenging"},{"key":"B","text":"galaxy. Challenging"},{"key":"C","text":"galaxy; challenging"},{"key":"D","text":"galaxy; therefore, challenging"}]$lyceon_json$::jsonb, 'A', NULL, E'The word "challenging" begins a participial phrase that modifies the entire preceding clause, describing the significance of the researchers'' identification. A comma correctly sets off this trailing participial modifier. Placing a period before "challenging" creates a sentence fragment, because "challenging the prevailing hypothesis..." lacks a subject and a finite verb and cannot stand alone as a sentence. A semicolon also fails here because a semicolon must join two independent clauses, and "challenging the prevailing hypothesis..." is not an independent clause. The semicolon paired with "therefore" compounds the same independent-clause error while also adding a conjunctive adverb that cannot introduce a participial phrase.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EGP8Q3', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, what is the main reason Okafor''s findings surprised other researchers in the field?', E'When Nigerian paleobotanist Chidera Okafor analyzed fossilized pollen grains extracted from 41-million-year-old sediment cores in the Niger Delta, she expected to find evidence of a tropical rainforest dominated by angiosperms, as had been documented at similar latitudes worldwide. Instead, Okafor''s 2021 analysis revealed that conifers — specifically members of the family Podocarpaceae — constituted nearly 63 percent of the pollen assemblage, a proportion far exceeding any previously recorded for equatorial Africa during the late Eocene. Other researchers had long assumed that the transition from conifer-dominated forests to angiosperm-dominated forests in equatorial Africa was complete by 45 million years ago, making Okafor''s discovery a significant challenge to the established timeline.', $lyceon_json$[{"key":"A","text":"Her sediment cores were extracted from a location in the Niger Delta that other researchers had not previously studied."},{"key":"B","text":"Her work contradicted the prevailing assumption that conifers had already been displaced by angiosperms in equatorial Africa by the time period she studied."},{"key":"C","text":"She used a novel method of analyzing fossilized pollen that yielded more precise species identifications than earlier techniques."},{"key":"D","text":"Her findings indicated that angiosperms were present in the Niger Delta much earlier than other researchers had predicted."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage states that other researchers assumed the transition from conifer- to angiosperm-dominated forests in equatorial Africa was complete by 45 million years ago, but Okafor''s 41-million-year-old samples showed conifers still dominant at 63 percent. The option about contradicting the prevailing assumption about conifers being displaced captures why this surprised the field. The option about the Niger Delta being previously unstudied is not supported by the passage, which focuses on the unexpected composition of the pollen rather than the novelty of the location. The option about a novel analytical method is not mentioned in the passage. The option about angiosperms arriving earlier reverses the finding: the surprise was that conifers persisted later than expected, not that angiosperms appeared earlier.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FC8SU1', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Paleoanthropologist Lee Berger''s 2013 discovery of Homo naledi fossils in South Africa''s Rising Star Cave system generated extraordinary public interest. The species displayed a mosaic of primitive and modern anatomical traits: a small brain case resembling Australopithecus alongside hands and feet adapted for tool use and bipedal walking. ________ the deliberate placement of remains deep within an almost inaccessible chamber suggested that Homo naledi may have practiced intentional body disposal, a behavior previously attributed only to species with significantly larger brains.', $lyceon_json$[{"key":"A","text":"Moreover,"},{"key":"B","text":"For instance,"},{"key":"C","text":"Accordingly,"},{"key":"D","text":"Instead,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents two separate remarkable aspects of Homo naledi: first, its mosaic anatomy, and second, the evidence for intentional body disposal. These are distinct but complementary reasons the discovery was extraordinary, so an additive transition signaling ''in addition'' is correct. ''For instance'' wrongly frames body disposal as an example of anatomical traits, when it is a behavioral finding, not an anatomical one. ''Accordingly'' wrongly implies the body-disposal evidence follows as a logical consequence of the anatomical traits. ''Instead'' wrongly signals that the body-disposal evidence replaces or contradicts the anatomical observations.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FUPBX3', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between Text 1 and Text 2?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H2C1V2', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the hypothesis described in the text?', E'Entomologist Renata Alves has proposed that the sharp decline in firefly populations observed across southeastern Brazil since 2014 is driven primarily by increased light pollution from expanding suburban developments rather than by pesticide use, which had been the previously favored explanation. Alves notes that fireflies rely on bioluminescent signals to locate mates, and she hypothesizes that artificial lighting disrupts this communication, reducing reproductive success.', $lyceon_json$[{"key":"A","text":"Firefly populations in regions with high pesticide use but low artificial lighting have remained stable over the same period."},{"key":"B","text":"Suburban developments in southeastern Brazil have expanded at a faster rate than in other regions of the country."},{"key":"C","text":"Several firefly species in southeastern Brazil produce bioluminescent signals at wavelengths different from those of common artificial lights."},{"key":"D","text":"Pesticide regulations in southeastern Brazil have become stricter since 2014, leading to reduced pesticide application overall."}]$lyceon_json$::jsonb, 'A', NULL, E'Alves hypothesizes that light pollution, not pesticides, drives firefly decline. The finding that firefly populations remain stable in areas with high pesticide use but low artificial lighting directly supports this by showing that pesticides alone do not cause decline while implicating light as the key variable. The option about suburban expansion rates establishes that development occurred faster in southeastern Brazil but does not connect this to firefly decline through the light-pollution mechanism. The option about different wavelengths would actually weaken the hypothesis by suggesting artificial light may not interfere with firefly signals. The option about stricter pesticide regulations partially supports the hypothesis by undermining the pesticide explanation, but it does not directly support the light-pollution mechanism itself — it only rules out an alternative.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HM4I8E', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The museum''s new conservation protocol requires technicians to catalog each artifact''s provenance, to photograph it under controlled lighting conditions from a minimum of six angles, ______ and to store it in a climate-regulated compartment maintained at 18 degrees Celsius and 43 percent relative humidity.', $lyceon_json$[{"key":"A","text":"the submission of a detailed condition report to the registrar's office,"},{"key":"B","text":"to submit a detailed condition report to the registrar's office,"},{"key":"C","text":"submitting a detailed condition report to the registrar's office,"},{"key":"D","text":"they submit a detailed condition report to the registrar's office,"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence presents a series of actions that the protocol requires technicians to perform, using infinitive phrases: "to catalog," "to photograph," and "to store." Parallel structure demands that the missing item also use an infinitive phrase. "To submit a detailed condition report to the registrar''s office" maintains the infinitive pattern established by the other items in the series. The noun phrase "the submission of" breaks the infinitive parallel by substituting a nominalization. The gerund "submitting" breaks the pattern by shifting to a different verb form that does not match the infinitive structure. The finite clause "they submit" breaks parallelism by introducing a new subject and conjugated verb where the pattern calls for an infinitive phrase governed by "requires technicians to."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I6QCCV', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does "confound" most nearly mean?', E'In a 2019 paper, geochemist Marta Eliassen challenged the prevailing model of mantle convection by presenting isotopic data from seventeen mid-ocean ridge basalt samples that appeared to confound the predicted correlation between strontium-87 ratios and ridge depth.', $lyceon_json$[{"key":"A","text":"exaggerate"},{"key":"B","text":"contradict"},{"key":"C","text":"verify"},{"key":"D","text":"obscure"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage states that Eliassen "challenged the prevailing model" by presenting data that appeared to confound a predicted correlation. In this scientific context, "confound" means to contradict or disprove—the data went against what the existing model predicted. "Exaggerate" is wrong because it means to overstate or amplify, and data does not amplify a correlation it conflicts with. "Verify" is wrong because it means to confirm, which is the opposite of challenging a model. "Obscure" is wrong because it means to make unclear or hide from view; the passage indicates the data actively went against the prediction rather than merely making it harder to detect.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IBPZYU', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Researchers at the University of Exeter have long studied the navigational abilities of dung beetles. In 2013, a team demonstrated that these insects use the Milky Way as a compass to roll their dung balls in straight lines. ________ their 2021 follow-up study revealed that the beetles can also navigate using polarized moonlight, adding another dimension to their remarkable orientation toolkit.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"In contrast,"},{"key":"D","text":"Consequently,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents two complementary findings about dung beetle navigation: the 2013 study on Milky Way navigation and the 2021 study on polarized moonlight. The blank connects two pieces of additive evidence, so the transition meaning ''in addition'' is correct. ''Nevertheless'' wrongly implies a concession or contrast. ''In contrast'' wrongly signals opposition between the two findings. ''Consequently'' wrongly implies the second finding was caused by the first.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LH96NI', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from Tanaka''s study, if true, would most directly undermine Hargrove''s claim as described in the text?', E'Literary historian Marcus Hargrove has argued that the serialized novels published in nineteenth-century American newspapers were primarily vehicles for moral instruction, contending that editors selected serials whose plots reinforced prevailing social values because doing so attracted subscribers who wanted their reading to serve an edifying purpose. Sociologist Emiko Tanaka, however, has challenged this view, noting that Hargrove''s analysis relied almost exclusively on editorial prefaces rather than on evidence of actual reader behavior. Tanaka''s own study examined 2,300 reader letters sent to seven newspapers between 1847 and 1889.', $lyceon_json$[{"key":"A","text":"The majority of reader letters praised serials for their suspenseful plots and entertaining characters rather than for any moral or instructional content."},{"key":"B","text":"Editors frequently revised the endings of serialized novels to align with reader preferences expressed in letters."},{"key":"C","text":"Newspapers that published serials with overtly moral themes had higher subscription rates than those that did not."},{"key":"D","text":"Reader letters were disproportionately written by a small, highly educated subset of the newspaper's overall readership."}]$lyceon_json$::jsonb, 'A', NULL, E'Hargrove claims that serialized novels served moral instruction and that subscribers wanted edifying reading. A finding that reader letters — direct evidence of reader behavior — praised serials for entertainment value rather than moral content would directly contradict both the purpose Hargrove assigns to the serials and the motivation he attributes to readers. The finding about editors revising endings addresses editorial responsiveness but does not speak to whether readers valued moral instruction or entertainment. The finding about higher subscription rates for morally themed serials would actually support Hargrove''s claim rather than undermine it. The finding about letters coming from a small educated subset raises questions about the representativeness of Tanaka''s own evidence but does not undermine Hargrove''s specific claim about the purpose of serialized novels.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 95, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MHESFI', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a brief profile of the sculptor El Anatsui for a museum newsletter and wants to highlight the contrast between his materials and the visual effect of his finished works. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NK87VY', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'Literary scholar Yumiko Tanabe has noted that while early twentieth-century critics dismissed haibun—a Japanese genre interweaving prose and haiku—as a minor curiosity, contemporary researchers increasingly recognize its structural sophistication. In Matsuo Bashō''s 1689 travelogue Oku no Hosomichi, for example, prose passages establish geographic and emotional context that the embedded haiku then compress into arresting images, creating a rhythmic alternation between discursive and concentrated modes of expression.', $lyceon_json$[{"key":"A","text":"It introduces a historical controversy and then resolves it by citing newly discovered evidence."},{"key":"B","text":"It presents a scholarly observation and then provides a specific example that illustrates it."},{"key":"C","text":"It defines a literary genre and then traces its influence on Western poetry."},{"key":"D","text":"It contrasts two competing interpretations of a single literary work."}]$lyceon_json$::jsonb, 'B', NULL, E'The text first presents Tanabe''s scholarly observation—that contemporary researchers now recognize haibun''s structural sophistication despite earlier dismissal—and then illustrates that observation with a specific example from Bashō''s Oku no Hosomichi. The claim about resolving a historical controversy with new evidence is wrong because there is no controversy being resolved and no newly discovered evidence cited; the shift is in critical reception, not evidentiary discovery. Tracing influence on Western poetry is wrong because the passage never mentions Western poetry or any cross-cultural literary influence. Contrasting two competing interpretations is wrong because only one interpretive perspective (Tanabe''s, aligned with contemporary scholars) is developed in detail.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PWB1GB', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 2019, marine archaeologist Tomás Herrera recovered a collection of seventeenth-century navigational instruments from a shipwreck near the ______ the instruments included an astrolabe, two cross-staffs, and a nocturnal, all dating to the early 1680s.', $lyceon_json$[{"key":"A","text":"Azores, the"},{"key":"B","text":"Azores. The"},{"key":"C","text":"Azores; instead, the"},{"key":"D","text":"Azores; nonetheless, the"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage contains two independent clauses: one describing the recovery of navigational instruments and another listing the specific instruments found. A period correctly separates these two independent clauses. Using a comma alone between them creates a comma splice, which is a sentence boundary error. The semicolon paired with "instead" incorrectly implies an alternative or replacement relationship, when the second clause simply elaborates on the first. The semicolon paired with "nonetheless" incorrectly implies a concession or contrast, but the second clause does not contradict or qualify the first—it merely identifies what was recovered.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QJAPX7', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a research participant would, if accurate, most effectively illustrate the concept described in the text?', E'Organizational psychologist Dmitri Volkov coined the term ''competence anchoring'' to describe a cognitive bias he observed in his 2022 study of 189 mid-career professionals. According to Volkov, competence anchoring occurs when individuals who have achieved expertise in one domain unconsciously resist learning new skills because they perceive the temporary incompetence required during the learning process as a threat to their professional identity. Rather than embracing the discomfort of being a novice, these individuals avoid unfamiliar tasks or delegate them, thereby limiting their own professional growth.', $lyceon_json$[{"key":"A","text":"\"I used to enjoy learning new software, but now that I'm a senior analyst, I feel like I should already know everything. Struggling with a new tool in front of my team would undermine the credibility I've built.\""},{"key":"B","text":"\"My company offers training programs every quarter, but I never sign up because the sessions are scheduled during my busiest work period and I can't afford to fall behind on deliverables.\""},{"key":"C","text":"\"I've been meaning to learn data visualization for years, but I keep putting it off because there are so many tools to choose from and I don't know which one would be most useful.\""},{"key":"D","text":"\"I delegate technical tasks to junior staff because I believe it gives them valuable experience and helps them develop skills they'll need for advancement.\""}]$lyceon_json$::jsonb, 'A', NULL, E'Competence anchoring involves resisting new learning because temporary incompetence threatens one''s professional identity. The quotation from the senior analyst who avoids struggling with new tools because it would undermine the credibility they have built directly illustrates this identity-threat mechanism. The quotation about scheduling conflicts describes a logistical barrier to learning, not an identity-based resistance. The quotation about indecision over which tool to learn describes choice paralysis, not a fear of appearing incompetent. The quotation about delegating for others'' benefit frames delegation as altruistic mentorship rather than avoidance driven by identity threat, which is the core of competence anchoring.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 85, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R1X1N8', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the third sentence in the overall structure of the text?', E'In a 2021 study, ecologist Priya Anand measured soil nitrogen levels beneath stands of black walnut trees (Juglans nigra) in three fragmented woodlots in southeastern Ohio. Contrary to the widespread assumption that juglone—a chemical the trees release through root exudation—uniformly suppresses neighboring plant growth, Anand found that several native understory species, including wild ginger and blue cohosh, exhibited root biomass increases of 14 to 23 percent in juglone-rich soils compared to control plots. Anand hypothesized that these species may have evolved biochemical tolerance mechanisms that allow them to exploit the reduced competition in the allelopathic zone.', $lyceon_json$[{"key":"A","text":"It introduces the methodology used to measure juglone concentrations across the study sites."},{"key":"B","text":"It qualifies the study's results by acknowledging limitations in the sample size."},{"key":"C","text":"It proposes an explanation for the findings described in the preceding sentence."},{"key":"D","text":"It provides additional experimental data that strengthen the study's primary conclusion."}]$lyceon_json$::jsonb, 'C', NULL, E'The third sentence presents Anand''s hypothesis—that the understory species evolved biochemical tolerance mechanisms enabling them to exploit reduced competition—which directly explains why those species showed increased root biomass in juglone-rich soils (the finding reported in the second sentence). Introducing methodology is wrong because the third sentence contains a hypothesis about evolutionary mechanisms, not a description of measurement procedures. Acknowledging sample size limitations is wrong because the sentence makes no mention of limitations, sample size, or caveats about the study''s scope. Providing additional experimental data is wrong because the sentence offers a theoretical explanation (a hypothesis about evolved tolerance), not new data points or measurements.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2T7H670', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing an article about the ecological role of beavers and wants to emphasize the scale of their environmental impact. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2THVU46', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'The assumption that cities are ecological wastelands has persisted for decades, but urban ecologist Priya Raghavan''s longitudinal study of moth diversity in Chennai, India, complicates this view. Raghavan documented 317 moth species across 14 urban sites between 2016 and 2022 — a number that exceeded the species count at two nearby rural reference sites by 11 percent. However, Raghavan cautions against interpreting this as evidence that urbanization benefits moths. Her data show that the urban species pool is dominated by generalists — species tolerant of artificial lighting, heat, and habitat fragmentation — while specialist species dependent on specific host plants declined by 38 percent over the study period. The higher overall count, Raghavan argues, masks a homogenization of the moth community that may eventually reduce urban moth diversity below rural levels as specialist populations continue to contract.', $lyceon_json$[{"key":"A","text":"Although Raghavan found more moth species in urban Chennai than at rural sites, this apparent diversity conceals a shift toward generalist species that may ultimately reduce urban moth diversity."},{"key":"B","text":"Raghavan's study demonstrates that urban areas are more ecologically productive than rural areas because they support a greater total number of moth species."},{"key":"C","text":"Raghavan's research confirms the longstanding assumption that cities function as ecological wastelands by showing that specialist moth species cannot survive in urban environments."},{"key":"D","text":"The decline of specialist moth species in Chennai is primarily caused by artificial lighting and heat rather than by habitat fragmentation."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Raghavan''s finding that urban Chennai had 11 percent more moth species than rural reference sites, then immediately complicates this by showing the urban species pool is dominated by generalists while specialists declined 38 percent. Raghavan argues the higher count masks a homogenization that may eventually reduce urban diversity below rural levels. The choice stating that apparent diversity conceals a shift toward generalist species with negative long-term implications captures this full arc correctly. The choice claiming urban areas are more ecologically productive stops at the surface-level finding of higher species counts and ignores Raghavan''s own caution against interpreting this as evidence that urbanization benefits moths. The choice claiming the study confirms the ecological-wasteland assumption misrepresents the passage, which states Raghavan''s work "complicates" rather than confirms that view, and the study found more total species in cities, not fewer. The choice attributing specialist decline primarily to artificial lighting and heat rather than habitat fragmentation misreads the passage, which lists all three together as conditions generalists tolerate — it does not rank these factors or claim one is the primary cause of specialist decline.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 95, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UH64EM', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Archaeologist Fatima El-Rashidi has studied the distribution of obsidian artifacts across settlements in ancient Mesopotamia. Obsidian does not occur naturally in the Mesopotamian lowlands; the nearest sources are volcanic deposits in eastern Anatolia, over 800 kilometers away. Yet El-Rashidi found obsidian tools and ornaments at lowland sites dating to 7500 BCE, well before any evidence of organized long-distance trade networks in the region. She concludes that the presence of obsidian at these early sites most likely indicates ________', $lyceon_json$[{"key":"A","text":"that obsidian was considered less valuable than locally available materials such as flint and limestone."},{"key":"B","text":"that informal, small-scale exchange between neighboring communities could move materials across vast distances over many generations."},{"key":"C","text":"that the volcanic deposits in eastern Anatolia were significantly larger during this period than they are today."},{"key":"D","text":"that Mesopotamian lowland settlements were established later than archaeologists had previously believed."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage establishes that obsidian traveled over 800 kilometers to lowland sites before organized trade networks existed. The most logical completion is that informal, small-scale exchanges between neighboring communities could cumulatively move materials vast distances over generations, which explains the presence of distant materials without requiring formal trade infrastructure. The option about obsidian being less valuable contradicts the fact that it was transported such a great distance, which suggests it was valued. The option about larger volcanic deposits is unsupported by the passage and would not explain how obsidian reached the lowlands regardless of deposit size. The option about settlements being established later contradicts the passage, which provides a specific date of 7500 BCE and does not question the dating of the settlements.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
