INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YUNGSY', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a research summary about coral reef conservation and wants to present a finding that challenges a commonly held assumption among marine biologists. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z7CG02', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'The ceramic artist Magdalena Suarez Frimkess spent decades creating hand-painted vessels inspired by cartoon imagery and Mexican folk art. Despite exhibiting in small galleries since the 1970s, she received scant critical attention for most of her career. ________ a 2014 retrospective at the South Willard gallery in Los Angeles catalyzed widespread recognition, leading museums such as the Hammer and LACMA to acquire her pieces.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"That is,"},{"key":"C","text":"However,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage first describes Suarez Frimkess receiving ''scant critical attention'' for most of her career, then states that a retrospective ''catalyzed widespread recognition.'' This is a clear contrast: prior obscurity versus subsequent acclaim. The transition meaning ''but'' or ''on the other hand'' correctly signals this shift. ''Similarly'' wrongly implies the recognition continued a pattern of obscurity. ''That is'' wrongly implies the recognition is a restatement of the obscurity. ''Meanwhile'' wrongly implies two simultaneous events rather than a contrasting development.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
